import cv2
cap = cv2.VideoCapture('/home/LOCAL_USER/.pipegen/factory-inputs/warehouse-workers-4281405-1080p.mp4')
if not cap.isOpened():
    raise RuntimeError('Cannot open warehouse video')
frame_index = 0
fps = float(cap.get(cv2.CAP_PROP_FPS)) or 25.0
try:
    while True:
        ok, frame = cap.read()
        if not ok:
            break
        height, width = frame.shape[:2]
        position_ms = float(cap.get(cv2.CAP_PROP_POS_MSEC))
        timestamp_s = position_ms / 1000.0 if position_ms > 0 else frame_index / fps
        metadata = {'frame_index': frame_index, 'timestamp_s': timestamp_s, 'timestamp_ns': int(round(timestamp_s * 1_000_000_000)), 'width': width, 'height': height}
        yield {'p01o_frame': frame, 'p01o_meta': metadata}
        frame_index += 1
finally:
    cap.release()
